    async def create_route(
        self,
        *,
        region: str | None = None,
        name: str | None = None,
        hub_id: str | None = None,
        topic: str | None = None,
        s3_config: CreateRouteRequestS3Config | None = None,
        db_config: CreateRouteRequestDatabaseConfig | None = None,
        rest_config: CreateRouteRequestRestConfig | None = None,
    ) -> Route:
        """
        Create a route

        Multiple kinds of routes can be created, such as:
        - Database Route
          Create a route that will record subscribed MQTT messages into your database.
          <b>You need to manage the database by yourself</b>.
        - REST Route.
          Create a route that will call a REST API on received subscribed MQTT messages.
        - Amazon S3 Routes.
          Create a route that will put subscribed MQTT messages into an Object Storage
              bucket.
          You need to create the bucket yourself and grant write access.
          Granting can be done with s3cmd (`s3cmd setacl s3://<my-bucket> --acl-
              grant=write:555c69c3-87d0-4bf8-80f1-99a2f757d031:555c69c3-87d0-4bf8-80f1-99a2f757d031`).

        Args:
            region: The region you want to target
            name: Route name.
            hub_id: Hub ID of the route.
            topic: Topic the route subscribes to. It must be a valid MQTT topic and up
                to 65535 characters.
            s3_config: If creating Amazon S3 Routes, Amazon S3-specific configuration
                fields. Precisely one of s3_config, db_config, rest_config can be set.
            db_config: If creating Database Route, DB-specific configuration fields.
                Precisely one of s3_config, db_config, rest_config can be set.
            rest_config: If creating Rest Route, Rest-specific configuration fields.
                Precisely one of s3_config, db_config, rest_config can be set.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/iot/v1/regions/{region}/routes", region=self._client.region(region)
            ),
            body={
                "name": name,
                "hub_id": hub_id,
                "topic": topic,
                "s3_config": s3_config,
                "db_config": db_config,
                "rest_config": rest_config,
            },
        )
        return Route.model_validate(data)

    async def get_route(
        self,
        *,
        route_id: str,
        region: str | None = None,
    ) -> Route:
        """
        Get a route

        Get information for a particular route, specified by the route ID. The response
        returns full details of the route, including its type, the topic it subscribes
        to and its configuration.

        Args:
            region: The region you want to target
            route_id: Route ID.
        """
        data = await self._client.request_json(
            "GET",
            self._client.path(
                "/iot/v1/regions/{region}/routes/{route_id}",
                region=self._client.region(region),
                route_id=route_id,
            ),
        )
        return Route.model_validate(data)

    async def update_route(
        self,
        *,
        route_id: str,
        region: str | None = None,
        name: str | None = None,
        topic: str | None = None,
        s3_config: UpdateRouteRequestS3Config | None = None,
        db_config: UpdateRouteRequestDatabaseConfig | None = None,
        rest_config: UpdateRouteRequestRestConfig | None = None,
    ) -> Route:
        """
        Update a route

        Update the parameters of an existing route, specified by its route ID.

        Args:
            region: The region you want to target
            route_id: Route id.
            name: Route name.
            topic: Topic the route subscribes to. It must be a valid MQTT topic and up
                to 65535 characters.
            s3_config: When updating Amazon S3 Route, Amazon S3-specific configuration
                fields. Precisely one of s3_config, db_config, rest_config can be set.
            db_config: When updating Database Route, DB-specific configuration fields.
                Precisely one of s3_config, db_config, rest_config can be set.
            rest_config: When updating Rest Route, Rest-specific configuration fields.
                Precisely one of s3_config, db_config, rest_config can be set.
        """
        data = await self._client.request_json(
            "PATCH",
            self._client.path(
                "/iot/v1/regions/{region}/routes/{route_id}",
                region=self._client.region(region),
                route_id=route_id,
            ),
            body={
                "name": name,
                "topic": topic,
                "s3_config": s3_config,
                "db_config": db_config,
                "rest_config": rest_config,
            },
        )
        return Route.model_validate(data)

